#!/usr/bin/env bash
# -*- coding: utf-8 -*-
# Build cli-skills source and wheel release distributions.
#
#/**
# * @file build.sh
# * @brief Build and validate release distributions under the repository dist directory.
# * @details Runs the release workflow's uv build command in temporary staging,
# *          validates archive structure, and publishes both outputs only after
# *          the full build succeeds. A checksummed manifest limits replacement
# *          and cleanup to artifacts previously generated by this script.
# * @satisfies PRJ-014 DES-084 DES-136 DES-137 DES-138 DES-139 DES-140 DES-141 DES-142
# */

set -Eeuo pipefail

#/** @brief Invocation path used to resolve the project root. */
SCRIPT_LOCATION=${BASH_SOURCE[0]}
#/** @brief Directory containing the invoked build script. */
SCRIPT_DIRECTORY=${SCRIPT_LOCATION%/*}
if [[ "$SCRIPT_DIRECTORY" == "$SCRIPT_LOCATION" ]]; then
    SCRIPT_DIRECTORY=.
fi
cd -- "$SCRIPT_DIRECTORY/.."
#/** @brief Absolute project root selected from the script location. */
PROJECT_ROOT=$PWD

#/** @brief Canonical release-artifact destination directory. */
DIST_DIRECTORY="$PROJECT_ROOT/dist"
#/** @brief Checksummed ownership manifest for generated distributions. */
MANIFEST_PATH="$DIST_DIRECTORY/.cli-skills-build-manifest"
#/** @brief Build mode: `build` publishes artifacts; `clean` removes owned artifacts. */
BUILD_MODE=build
#/** @brief Temporary external directory holding build output and rollback copies. */
STAGING_DIRECTORY=
#/** @brief Temporary directory inside dist used for same-filesystem publication. */
PUBLISH_DIRECTORY=
#/** @brief Whether this process created its staging directory. */
STAGING_CREATED=0
#/** @brief Whether this process created the publication staging directory. */
PUBLISH_DIRECTORY_CREATED=0
#/** @brief Whether build intermediates were absent and are owned by this run. */
BUILD_OUTPUTS_OWNED=0
#/** @brief Whether the generated-artifact replacement transaction has started. */
PUBLISH_STARTED=0
#/** @brief Whether the generated-artifact replacement transaction committed. */
PUBLISH_COMMITTED=0
#/** @brief Whether this process acquired the build lock directory. */
BUILD_LOCK_OWNED=0
#/** @brief SHA-256 utility selected from the available system toolchain. */
SHA256_TOOL=
#/** @brief Previously recorded generated distribution filenames. */
MANIFEST_FILES=()
#/** @brief Previously recorded SHA-256 digests aligned with `MANIFEST_FILES`. */
MANIFEST_DIGESTS=()
#/** @brief Existing manifest-owned files backed up for publication rollback. */
BACKED_UP_FILES=()
#/** @brief New artifact paths touched by the publication transaction. */
PUBLISHED_FILES=()
#/** @brief New artifact filenames selected from the staging build. */
NEW_ARTIFACT_NAMES=()
#/** @brief New artifact digests aligned with `NEW_ARTIFACT_NAMES`. */
NEW_ARTIFACT_DIGESTS=()

#/**
# * @brief Emit a fatal diagnostic and terminate the build.
# * @details Writes one actionable message to stderr and exits with status 1.
# * @param message {string} Failure detail without a required trailing newline.
# * @return {never} Does not return.
# * @satisfies DES-136 DES-138 DES-141 DES-142
# */
die() {
    printf 'ERROR: %s\n' "$1" >&2
    exit 1
}

#/**
# * @brief Calculate the SHA-256 digest of one file.
# * @details Uses the selected platform utility and emits only its 64-character
# *          hexadecimal digest; utility failures propagate through pipefail.
# * @param path {string} Existing regular file path.
# * @return {string} Lowercase SHA-256 digest.
# * @satisfies DES-140
# */
sha256_file() {
    local output
    if [[ "$SHA256_TOOL" == sha256sum ]]; then
        output=$(sha256sum -- "$1")
    else
        output=$(shasum -a 256 -- "$1")
    fi
    printf '%s\n' "${output%% *}"
}

#/**
# * @brief Determine whether one repository-relative path is tracked by Git.
# * @details Uses a path-limited index query; no repository state is modified.
# * @param relative_path {string} Path relative to the repository root.
# * @return {bool} Success when Git tracks the path.
# * @satisfies DES-139 DES-141
# */
is_tracked() {
    git -C "$PROJECT_ROOT" ls-files --error-unmatch -- "$1" >/dev/null 2>&1
}

#/**
# * @brief Parse and verify the generated-distribution ownership manifest.
# * @details Validates the version header, filename allowlist, digest syntax,
# *          duplicate entries, tracked-file exclusion, and every present file
# *          digest before exposing manifest records to cleanup or replacement.
# * @return {int} Zero when the manifest is valid or absent; nonzero on corruption.
# * @throws {SystemExit} When a manifest entry is malformed or unsafe to remove.
# * @satisfies DES-139 DES-140 DES-141
# */
load_manifest() {
    local header digest filename relative_path actual_digest existing
    local index
    MANIFEST_FILES=()
    MANIFEST_DIGESTS=()

    if [[ ! -e "$MANIFEST_PATH" && ! -L "$MANIFEST_PATH" ]]; then
        return 0
    fi
    [[ -f "$MANIFEST_PATH" && ! -L "$MANIFEST_PATH" ]] ||
        die "Build manifest is not a regular file: $MANIFEST_PATH"
    is_tracked "dist/.cli-skills-build-manifest" &&
        die "Build manifest is tracked and will not be modified."

    exec 3< "$MANIFEST_PATH"
    if ! IFS= read -r header <&3; then
        exec 3<&-
        die "Build manifest is empty: $MANIFEST_PATH"
    fi
    if [[ "$header" != "cli-skills-build-manifest-v1" ]]; then
        exec 3<&-
        die "Unsupported build manifest format: $MANIFEST_PATH"
    fi

    while IFS=$'\t' read -r digest filename <&3; do
        [[ -n "$digest" && -n "$filename" ]] || {
            exec 3<&-
            die "Build manifest contains an empty entry."
        }
        [[ "$digest" =~ ^[[:xdigit:]]{64}$ ]] || {
            exec 3<&-
            die "Build manifest contains an invalid SHA-256 digest."
        }
        [[ "$filename" =~ ^cli_skills-[A-Za-z0-9.+_-]+\.(tar\.gz|whl)$ ]] || {
            exec 3<&-
            die "Build manifest contains an unsafe artifact path: $filename"
        }
        for existing in "${MANIFEST_FILES[@]}"; do
            [[ "$existing" != "$filename" ]] || {
                exec 3<&-
                die "Build manifest contains a duplicate artifact: $filename"
            }
        done
        relative_path="dist/$filename"
        is_tracked "$relative_path" && {
            exec 3<&-
            die "Recorded release artifact is tracked and will not be removed: $relative_path"
        }
        if [[ -e "$DIST_DIRECTORY/$filename" || -L "$DIST_DIRECTORY/$filename" ]]; then
            [[ -f "$DIST_DIRECTORY/$filename" && ! -L "$DIST_DIRECTORY/$filename" ]] || {
                exec 3<&-
                die "Recorded artifact is not a regular file: $relative_path"
            }
            actual_digest=$(sha256_file "$DIST_DIRECTORY/$filename")
            [[ "$actual_digest" == "$digest" ]] || {
                exec 3<&-
                die "Recorded artifact was modified; preserving it: $relative_path"
            }
        fi
        MANIFEST_FILES+=("$filename")
        MANIFEST_DIGESTS+=("$digest")
    done
    exec 3<&-

    for index in "${!MANIFEST_FILES[@]}"; do
        [[ -n "${MANIFEST_DIGESTS[$index]}" ]] ||
            die "Build manifest digest index is inconsistent."
    done
}

#/**
# * @brief Restore the previous distribution set after an incomplete publication.
# * @details Removes every path touched by the current transaction, then restores
# *          checksum-verified prior artifacts and the prior manifest from backup.
# *          Returns failure if any rollback filesystem operation fails.
# * @return {int} Zero when rollback succeeds; nonzero when restoration fails.
# * @satisfies DES-138 DES-139 DES-140
# */
rollback_publication() {
    local status=0 filename
    (( PUBLISH_STARTED == 1 && PUBLISH_COMMITTED == 0 )) || return 0

    for filename in "${PUBLISHED_FILES[@]}"; do
        if [[ -e "$DIST_DIRECTORY/$filename" ]] &&
            ! rm -f -- "$DIST_DIRECTORY/$filename"; then
            printf 'ERROR: Could not remove partial artifact: %s\n' "$filename" >&2
            status=1
        fi
    done
    if [[ -n "$STAGING_DIRECTORY" && -d "$STAGING_DIRECTORY/backup" ]]; then
        for filename in "${BACKED_UP_FILES[@]}"; do
            if [[ -f "$STAGING_DIRECTORY/backup/$filename" ]] &&
                ! cp -p -- "$STAGING_DIRECTORY/backup/$filename" "$DIST_DIRECTORY/$filename"; then
                printf 'ERROR: Could not restore previous artifact: %s\n' "$filename" >&2
                status=1
            fi
        done
        if [[ -f "$STAGING_DIRECTORY/backup/.cli-skills-build-manifest" ]] &&
            ! cp -p -- "$STAGING_DIRECTORY/backup/.cli-skills-build-manifest" "$MANIFEST_PATH"; then
            printf 'ERROR: Could not restore the previous build manifest.\n' >&2
            status=1
        elif [[ ! -f "$STAGING_DIRECTORY/backup/.cli-skills-build-manifest" ]] &&
            [[ -e "$MANIFEST_PATH" ]] && ! rm -f -- "$MANIFEST_PATH"; then
            printf 'ERROR: Could not remove the partial build manifest.\n' >&2
            status=1
        fi
    fi
    return "$status"
}

#/**
# * @brief Remove generated build intermediates owned by this invocation.
# * @details Deletes only the root `build/` output and source `egg-info`
# *          directories after preflight established their absence. The cleanup
# *          trap runs on success, failure, and handled signals.
# * @return {int} Zero when all cleanup operations succeed.
# * @satisfies DES-139 DES-144
# */
cleanup() {
    local status=0
    if (( PUBLISH_STARTED == 1 && PUBLISH_COMMITTED == 0 )); then
        if ! rollback_publication; then
            status=1
        fi
    fi
    if (( BUILD_OUTPUTS_OWNED == 1 )); then
        if [[ -e "$PROJECT_ROOT/build" ]] && ! rm -rf -- "$PROJECT_ROOT/build"; then
            printf 'ERROR: Could not remove generated build directory.\n' >&2
            status=1
        fi
        if ! find "$PROJECT_ROOT/src" -type d -name '*.egg-info' -prune \
            -exec rm -rf -- {} +; then
            printf 'ERROR: Could not remove generated source intermediates.\n' >&2
            status=1
        fi
    fi
    if (( PUBLISH_DIRECTORY_CREATED == 1 )) &&
        [[ -d "$PUBLISH_DIRECTORY" ]] && ! rm -rf -- "$PUBLISH_DIRECTORY"; then
        printf 'ERROR: Could not remove publication staging directory.\n' >&2
        status=1
    fi
    if (( STAGING_CREATED == 1 )) &&
        [[ -d "$STAGING_DIRECTORY" ]] && ! rm -rf -- "$STAGING_DIRECTORY"; then
        printf 'ERROR: Could not remove build staging directory.\n' >&2
        status=1
    fi
    if (( BUILD_LOCK_OWNED == 1 )) &&
        [[ -f "$PROJECT_ROOT/.cli-skills-build.lock/preexisting-source-artifacts" ]] &&
        ! rm -f -- "$PROJECT_ROOT/.cli-skills-build.lock/preexisting-source-artifacts"; then
        printf 'ERROR: Could not remove the build-lock preflight record.\n' >&2
        status=1
    fi
    if (( BUILD_LOCK_OWNED == 1 )) &&
        [[ -d "$PROJECT_ROOT/.cli-skills-build.lock" ]] &&
        ! rmdir -- "$PROJECT_ROOT/.cli-skills-build.lock"; then
        printf 'ERROR: Could not release the build lock.\n' >&2
        status=1
    fi
    return "$status"
}

#/**
# * @brief Preserve the original build result while enforcing successful cleanup.
# * @details The EXIT handler records the triggering status, disables recursive
# *          traps, executes cleanup, and promotes cleanup failure to error only
# *          when the build itself had succeeded. It prints a final status after
# *          cleanup has completed.
# * @return {never} Exits with the original or cleanup-failure status.
# * @satisfies DES-139 DES-144
# */
finish() {
    local original_status=$?
    local cleanup_status=0
    trap - EXIT ERR INT TERM HUP
    if ! cleanup; then
        cleanup_status=1
    fi
    if (( original_status == 0 && cleanup_status != 0 )); then
        original_status=1
    fi
    if (( original_status == 0 )); then
        if [[ "$BUILD_MODE" == clean ]]; then
            printf 'Generated release artifacts removed safely.\n'
        elif [[ "$BUILD_MODE" == help ]]; then
            printf 'Usage: scripts/build.sh [--clean-generated]\n'
        else
            printf 'Build succeeded; release artifacts in %s:\n' "$DIST_DIRECTORY"
            printf '  %s\n' "${NEW_ARTIFACT_NAMES[@]/#/$DIST_DIRECTORY/}"
        fi
    else
        printf 'ERROR: Build failed with status %d.\n' "$original_status" >&2
    fi
    exit "$original_status"
}

#/**
# * @brief Record a command failure with the active phase and exit status.
# * @details ERR and signal handlers converge on the EXIT cleanup path; an
# *          existing failed command status is never replaced by cleanup success.
# * @param status {int} Original nonzero command status.
# * @param phase {string} Failed command text or signal name.
# * @return {never} Exits with the original failure status.
# * @satisfies DES-138 DES-144
# */
on_error() {
    local status=$1
    local phase=$2
    printf 'ERROR: Build phase failed: %s (status %d).\n' "$phase" "$status" >&2
    exit "$status"
}

trap finish EXIT
trap 'on_error "$?" "$BASH_COMMAND"' ERR
trap 'on_error 130 INT' INT
trap 'on_error 143 TERM' TERM
trap 'on_error 129 HUP' HUP

if (( $# > 1 )); then
    die 'Usage: scripts/build.sh [--clean-generated]'
fi
if (( $# == 1 )); then
    case "$1" in
        --clean-generated)
            BUILD_MODE=clean
            ;;
        --help)
            BUILD_MODE=help
            exit 0
            ;;
        *)
            die "Unknown argument: $1"
            ;;
    esac
fi

[[ -f "$PROJECT_ROOT/pyproject.toml" && -f "$PROJECT_ROOT/uv.lock" &&
    -f "$PROJECT_ROOT/.github/workflows/release-pypi.yml" ]] ||
    die 'Project metadata, lockfile, or release workflow is missing.'
command -v git >/dev/null 2>&1 || die 'Required tool is unavailable: git.'
if [[ "$BUILD_MODE" == build ]]; then
    command -v uv >/dev/null 2>&1 || die 'Required tool is unavailable: uv.'
    command -v tar >/dev/null 2>&1 || die 'Required tool is unavailable: tar.'
fi
if command -v sha256sum >/dev/null 2>&1; then
    SHA256_TOOL=sha256sum
elif command -v shasum >/dev/null 2>&1; then
    SHA256_TOOL=shasum
else
    die 'Required SHA-256 utility is unavailable (sha256sum or shasum).'
fi

if [[ -L "$DIST_DIRECTORY" ]]; then
    die 'The dist directory must not be a symbolic link.'
fi
if [[ -e "$DIST_DIRECTORY" && ! -d "$DIST_DIRECTORY" ]]; then
    die 'The dist path exists and is not a directory.'
fi
if [[ "$BUILD_MODE" == clean && ! -e "$DIST_DIRECTORY" ]]; then
    exit 0
fi
mkdir -p -- "$DIST_DIRECTORY"

if [[ "$BUILD_MODE" == clean ]]; then
    load_manifest
    if [[ ! -e "$MANIFEST_PATH" && ! -L "$MANIFEST_PATH" ]]; then
        shopt -s nullglob
        for artifact in "$DIST_DIRECTORY"/cli_skills-*.tar.gz "$DIST_DIRECTORY"/cli_skills-*.whl; do
            [[ ! -e "$artifact" && ! -L "$artifact" ]] ||
                die "Unrecorded release artifact will be preserved: $artifact"
        done
        exit 0
    fi
    for artifact in "${MANIFEST_FILES[@]}"; do
        if [[ -e "$DIST_DIRECTORY/$artifact" ]] &&
            ! rm -f -- "$DIST_DIRECTORY/$artifact"; then
            die "Could not remove generated artifact: $artifact"
        fi
    done
    rm -f -- "$MANIFEST_PATH" || die 'Could not remove the build manifest.'
    exit 0
fi

[[ ! -e "$PROJECT_ROOT/.cli-skills-build.lock" &&
    ! -L "$PROJECT_ROOT/.cli-skills-build.lock" ]] ||
    die 'Another build is active or an earlier build lock requires inspection.'
mkdir -- "$PROJECT_ROOT/.cli-skills-build.lock"
BUILD_LOCK_OWNED=1

if [[ -e "$PROJECT_ROOT/build" || -L "$PROJECT_ROOT/build" ]]; then
    die 'Pre-existing build/ output prevents safe cleanup; remove or preserve it manually.'
fi
find "$PROJECT_ROOT/src" -name '*.egg-info' -print -quit \
    > "$PROJECT_ROOT/.cli-skills-build.lock/preexisting-source-artifacts"
[[ ! -s "$PROJECT_ROOT/.cli-skills-build.lock/preexisting-source-artifacts" ]] ||
    die 'Pre-existing source build artifacts prevent safe cleanup.'

load_manifest
shopt -s nullglob
for artifact in "$DIST_DIRECTORY"/cli_skills-*.tar.gz "$DIST_DIRECTORY"/cli_skills-*.whl; do
    artifact_name=${artifact##*/}
    known=0
    for previous_name in "${MANIFEST_FILES[@]}"; do
        if [[ "$previous_name" == "$artifact_name" ]]; then
            known=1
            break
        fi
    done
    (( known == 1 )) ||
        die "Unrecorded release artifact will be preserved: $artifact"
done

if compgen -G "$DIST_DIRECTORY/.cli-skills-build.*" >/dev/null; then
    die 'Pre-existing distribution staging output requires inspection.'
fi
STAGING_DIRECTORY=$(mktemp -d "${TMPDIR:-/tmp}/cli-skills-build.XXXXXX")
STAGING_CREATED=1
mkdir -- "$STAGING_DIRECTORY/backup"

if [[ "$BUILD_MODE" != build ]]; then
    die 'Invalid build mode.'
fi

printf '==> Validating release toolchain and locked project configuration\n'
uv --version
uv lock --check

printf '==> Building source distribution and wheel in isolated staging\n'
BUILD_OUTPUTS_OWNED=1
PYTHONDONTWRITEBYTECODE=1 UV_PROJECT_ENVIRONMENT="$STAGING_DIRECTORY/venv" \
    uv run --frozen --with build python -m build --outdir "$STAGING_DIRECTORY"

sdists=("$STAGING_DIRECTORY"/cli_skills-*.tar.gz)
wheels=("$STAGING_DIRECTORY"/cli_skills-*.whl)
(( ${#sdists[@]} == 1 )) || die 'Build did not produce exactly one source distribution.'
(( ${#wheels[@]} == 1 )) || die 'Build did not produce exactly one wheel.'
[[ -s "${sdists[0]}" && -s "${wheels[0]}" ]] ||
    die 'A generated distribution is empty.'

printf '==> Validating source and wheel archive structures\n'
tar -tzf "${sdists[0]}" > "$STAGING_DIRECTORY/sdist-contents.txt"
[[ -s "$STAGING_DIRECTORY/sdist-contents.txt" ]] ||
    die 'Source distribution archive has no entries.'
PYTHONDONTWRITEBYTECODE=1 UV_PROJECT_ENVIRONMENT="$STAGING_DIRECTORY/venv" \
    uv run --frozen python -m zipfile -t "${wheels[0]}"

NEW_ARTIFACT_NAMES=("${sdists[0]##*/}" "${wheels[0]##*/}")
NEW_ARTIFACT_DIGESTS+=("$(sha256_file "${sdists[0]}")")
NEW_ARTIFACT_DIGESTS+=("$(sha256_file "${wheels[0]}")")

is_tracked "dist/.cli-skills-build-manifest" &&
    die 'The build manifest path is tracked and will not be modified.'
for artifact_name in "${NEW_ARTIFACT_NAMES[@]}"; do
    target_path="$DIST_DIRECTORY/$artifact_name"
    is_tracked "dist/$artifact_name" &&
        die "Release artifact target is tracked: $target_path"
    known=0
    for previous_name in "${MANIFEST_FILES[@]}"; do
        if [[ "$previous_name" == "$artifact_name" ]]; then
            known=1
            break
        fi
    done
    if [[ -e "$target_path" || -L "$target_path" ]] && (( known == 0 )); then
        die "Release artifact target is unrecorded and will be preserved: $target_path"
    fi
done

PUBLISH_DIRECTORY=$(mktemp -d "$DIST_DIRECTORY/.cli-skills-build.XXXXXX")
PUBLISH_DIRECTORY_CREATED=1
for artifact_index in "${!NEW_ARTIFACT_NAMES[@]}"; do
    artifact_name=${NEW_ARTIFACT_NAMES[$artifact_index]}
    source_artifact="$STAGING_DIRECTORY/$artifact_name"
    cp -p -- "$source_artifact" "$PUBLISH_DIRECTORY/$artifact_name"
done
{
    printf 'cli-skills-build-manifest-v1\n'
    for artifact_index in "${!NEW_ARTIFACT_NAMES[@]}"; do
        printf '%s\t%s\n' \
            "${NEW_ARTIFACT_DIGESTS[$artifact_index]}" \
            "${NEW_ARTIFACT_NAMES[$artifact_index]}"
    done
} > "$PUBLISH_DIRECTORY/.cli-skills-build-manifest"

for artifact_name in "${MANIFEST_FILES[@]}"; do
    previous_path="$DIST_DIRECTORY/$artifact_name"
    if [[ -f "$previous_path" ]]; then
        cp -p -- "$previous_path" "$STAGING_DIRECTORY/backup/$artifact_name"
        BACKED_UP_FILES+=("$artifact_name")
    fi
done
if [[ -f "$MANIFEST_PATH" ]]; then
    cp -p -- "$MANIFEST_PATH" "$STAGING_DIRECTORY/backup/.cli-skills-build-manifest"
fi

PUBLISH_STARTED=1
for artifact_name in "${MANIFEST_FILES[@]}"; do
    if [[ -e "$DIST_DIRECTORY/$artifact_name" ]]; then
        rm -f -- "$DIST_DIRECTORY/$artifact_name"
    fi
done
for artifact_name in "${NEW_ARTIFACT_NAMES[@]}"; do
    PUBLISHED_FILES+=("$artifact_name")
    mv -- "$PUBLISH_DIRECTORY/$artifact_name" "$DIST_DIRECTORY/$artifact_name"
done
PUBLISHED_FILES+=(".cli-skills-build-manifest")
mv -- "$PUBLISH_DIRECTORY/.cli-skills-build-manifest" "$MANIFEST_PATH"
PUBLISH_COMMITTED=1
